import java.io.*;
import java.util.*;

public class A {
    private static boolean check(long W, long M, long x) {
        if (x == M) return true;
        x += M;
        while (x > 0) {
            if (x % W > 1) return false;
            x /= W;
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] s = br.readLine().trim().split(" ");
        long W = Long.parseLong(s[0]);
        long M = Long.parseLong(s[1]);

        if (W == 2) {
            System.out.println("YES");
            System.exit(0);
        }

        ArrayList<Long> powers = new ArrayList<>();
        powers.add(1L);
        powers.add(W);
        long cur = W;
        while (true) {
            cur *= W;
            if (cur < 0 || cur > 10000000000L) break;
            powers.add(cur);
        }

        ArrayDeque<long[]> stack = new ArrayDeque<>();
        stack.push(new long[]{0L, 0L});
        boolean found = false;

        while (!stack.isEmpty()) {
            long[] state = stack.pop();
            int idx = (int) state[0];
            long sum = state[1];

            if (idx == powers.size()) {
                if (check(W, M, sum)) {
                    found = true;
                    break;
                }
            } else {
                stack.push(new long[]{idx + 1L, sum});
                stack.push(new long[]{idx + 1L, sum + powers.get(idx)});
            }
        }

        System.out.println(found ? "YES" : "NO");
    }
}
